BEGIN SELECT N'skipped (already there)' AS result; RETURN; END;

DECLARE @u UNIQUEIDENTIFIER = (SELECT TOP 1 u.user_id FROM Users u JOIN UserRoles ur ON ur.user_id = u.user_id JOIN Roles r ON r.role_id = ur.role_id
