IF @top IS NULL BEGIN SET @top = NEWID(); INSERT INTO Folders (folder_id, folder_name, parent_id, created_by) VALUES (@top, N'DAILY METAL DETECTOR SENSITIVITY TEST REPORT', NULL, @u); END;
DECLARE @sub UNIQUEIDENTIFIER = (SELECT TOP 1 folder_id FROM Folders WHERE is_deleted = 0 AND parent_id = @top AND folder_name = N'MD Record Problem' ORDER BY created_at);
IF @sub IS NULL BEGIN SET @sub = NEWID(); INSERT INTO Folders (folder_id, folder_name, parent_id, created_by) VALUES (@sub, N'MD Record Problem', @top, @u); END;





